const mainBootStartedAt = performance.now();
const markPerformancePhase = (name: string) => {
  if (__NAIMAGE_PERF_PROBE__) performance.mark(`naimage:${name}`);
};
markPerformancePhase("main-module");
let firstAppRenderMarked = false;
let firstWorkspaceRenderMarked = false;
const bootLog = (stage: string) => {
  console.info(`[naimage boot +${Math.round(performance.now() - mainBootStartedAt)}ms] ${stage}`);
};
const stageSize = { width: 24000, height: 18000 };
const WORLD_MARGIN = 12000;
const initialViewport: CanvasViewport = { x: 72, y: 58, scale: 0.9 };

function canvasViewportTransform(viewport: CanvasViewport, accelerated = false) {
  const dpr = typeof window === "undefined" ? 1 : clamp(Number(window.devicePixelRatio || 1), 1, 4);
  const alignedX = Math.round(viewport.x * dpr) / dpr;
  const alignedY = Math.round(viewport.y * dpr) / dpr;
  const scale = Math.round(viewport.scale * 10000) / 10000;
  // translate3d keeps active wheel/pan gestures responsive, but leaving the
  // entire canvas promoted permanently makes Chromium reuse a scaled texture
  // and softens DOM text, SVG edges and image previews. Return to a 2D
  // transform at rest so Chromium can rasterize the settled scale sharply.
  return accelerated
    ? `translate3d(${alignedX}px, ${alignedY}px, 0) scale(${scale})`
    : `translate(${alignedX}px, ${alignedY}px) scale(${scale})`;
}
const ZOOM_MIN = 0.18;
const ZOOM_MAX = 2.4;
// Keep React out of a continuous wheel gesture. A shorter debounce can fire
// between slower frames on dense canvases and force a full reconciliation
// while Chromium is still compositing the transient stage transform.
const VIEWPORT_WHEEL_COMMIT_DELAY_MS = 240;
const NODE_W = 260;
const REQUIREMENT_NODE_W = 320;
const REQUIREMENT_NODE_H = 230;
const IMAGE_CONTAINER_W = 420;
const IMAGE_CONTAINER_H = 410;
const IMAGE_CONTAINER_MIN_W = 360;
const IMAGE_CONTAINER_MIN_H = 300;
const IMAGE_COLLECTION_W = 420;
const IMAGE_COLLECTION_BATCH_H = 410;
const IMAGE_COLLECTION_SERIES_H = 330;
const VIDEO_NODE_W = 440;
const VIDEO_NODE_H = 340;
const LAYER_STACK_W = 430;
const LAYER_STACK_H = 500;
const NODE_CONNECT_Y = 40;
const NODE_RESIZE_MIN_W = 260;
const NODE_RESIZE_MAX_W = 720;
// Keep roughly one node stride around the viewport. A 1000px buffer mounted
// dozens of fully interactive image cards and every nearby relation before
// the first paint, which produced a visible startup stall on large projects.
const NODE_RENDER_BUFFER = 520;
// At overview zoom a full image card is smaller than a usable control anyway.
// Keep large canvases interactive by rendering a lightweight, still selectable
// node silhouette until the user selects a node or zooms in for editing.
const NODE_OVERVIEW_MAX_SCALE = 0.3;
const NODE_OVERVIEW_MIN_COUNT = 80;
const NODE_OVERVIEW_MIN_IMAGE_TILES = 10;
