function progressInputOperation(progress?: AgentProgress | null) {
  const input = progress?.input;
  if (!input || typeof input !== "object" || Array.isArray(input)) return "";
  return String((input as Record<string, unknown>).operation || "");
}
const NODE_RESIZE_MIN_H = 220;
const NODE_RESIZE_MAX_H = 900;
const initialNodes: WorkflowNode[] = [];

type ConnectionDraft = {
  sourceId: string;
  sourceIds: string[];
  worldX: number;
  worldY: number;
};

function provenancePortCenter(node: WorkflowNode, side: "input" | "output") {
  const { renderWidth, renderHeight, nodeMinimum } = workflowNodeRenderMetrics(node);
  const height = renderHeight ?? nodeMinimum.height ?? NODE_RESIZE_MIN_H;
  return {
    x: side === "output" ? node.x + renderWidth : node.x,
    y: node.y + height / 2
  };
}

function provenanceEdgePath(
  source: WorkflowNode,
  target: WorkflowNode,
  laneIndex = 0,
  laneCount = 1
) {
  const sourcePort = provenancePortCenter(source, "output");
  const targetPort = provenancePortCenter(target, "input");
  const x1 = sourcePort.x;
  const y1 = sourcePort.y;
  const x2 = targetPort.x;
  const y2 = targetPort.y;
  const lane = (laneIndex - (laneCount - 1) / 2) * 34;
  const mid = (x1 + x2) / 2;
  return `M ${x1} ${y1} C ${mid} ${y1 + lane}, ${mid} ${y2 + lane}, ${x2} ${y2}`;
}

function parentImageActionToRequirement(action: AgentRuntimeAction, requirementNodeId: string): AgentRuntimeAction {
  if (!requirementNodeId || action.type !== "workflow.node.create" || action.node?.nodeType !== "image") return action;
  return {
    ...action,
    node: {
      ...action.node,
      parentId: requirementNodeId,
      relationType: action.node.imageParams?.layerGroupId ? "grouped" as const : "derived-from" as const,
      imageCollection: action.node.imageCollection
        ? { ...action.node.imageCollection, sourceNodeId: requirementNodeId }
        : undefined
    }
  };
}

