  function clearGoalConfirmationAuthorizations() {
    goalConfirmationLedgerRef.current?.clear();
    agentWindowGoalPreviewRef.current = null;
  }

  function revokeGoalConfirmation(preview: GoalModePreview | null | undefined) {
    if (preview?.confirmationHash) goalConfirmationLedgerRef.current?.invalidate(preview.confirmationHash);
    if (agentWindowGoalPreviewRef.current?.confirmationHash === preview?.confirmationHash) {
      agentWindowGoalPreviewRef.current = null;
    }
  }

  function currentNodeSelection(): NodeSelectionState {
    return {
      primaryId: selectedNodeIdRef.current,
      ids: [...selectedNodeIdsRef.current]
    };
  }

  function commitNodeSelection(next: NodeSelectionState, gesture: string) {
    const samePrimary = selectedNodeIdRef.current === next.primaryId;
    const sameIds = selectedNodeIdsRef.current.length === next.ids.length &&
      selectedNodeIdsRef.current.every((id, index) => id === next.ids[index]);
    if (samePrimary && sameIds) {
      selectionGestureRef.current = gesture;
      return;
    }
    selectedNodeIdRef.current = next.primaryId;
    selectedNodeIdsRef.current = [...next.ids];
    selectionGestureRef.current = gesture;
    if (!samePrimary) setPrimarySelectedNodeId(next.primaryId);
    if (!sameIds) setSelectedNodeIds([...next.ids]);
  }

  function applyNodeSelection(
    action: NodeSelectionAction,
    gesture: string,
    validateAvailableIds = false
  ) {
    const availableIds = validateAvailableIds
      ? new Set(nodesRef.current.map((node) => node.id))
      : undefined;
    commitNodeSelection(reduceNodeSelection(currentNodeSelection(), action, availableIds), gesture);
  }

  function replaceSelectedNodeId(value: string | ((current: string) => string)) {
    const current = selectedNodeIdRef.current;
    const next = typeof value === "function" ? value(current) : value;
    applyNodeSelection(next ? { type: "replace", id: next } : { type: "clear" }, "explicit-replace");
  }

  function setSelectedNodeId(value: string | ((current: string) => string)) {
    const current = selectedNodeIdRef.current;
    const next = typeof value === "function" ? value(current) : value;
    applyNodeSelection(next ? { type: "focus", id: next } : { type: "clear" }, "programmatic-focus");
  }

  function selectNodeFromPlainClick(nodeId: string, gesture = "plain-click") {
    applyNodeSelection({ type: "plain-click", id: nodeId }, gesture, true);
  }

  function removeNodeIdsFromSelection(removeIds: Set<string>) {
    applyNodeSelection({ type: "remove", ids: [...removeIds] }, "remove-nodes");
  }

  function selectCanvas() {
    applyNodeSelection({ type: "clear" }, "explicit-clear");
  }

  function selectNodeGroup(ids: string[], requestedPrimaryId = "") {
    applyNodeSelection({ type: "replace-group", ids, primaryId: requestedPrimaryId }, "group-replace", true);
  }

  function toggleNodeSelection(nodeId: string) {
    applyNodeSelection({ type: "toggle", id: nodeId }, "modifier-toggle", true);
  }

  function captureCanvasHistorySnapshot(label: string): CanvasHistorySnapshot {
    return {
      label,
      nodes: nodesRef.current.map(cloneWorkflowNode),
      layoutGroups: layoutGroupsRef.current.map((group) => ({ ...group, memberNodeIds: [...group.memberNodeIds] })),
      selection: currentNodeSelection()
    };
  }

  function pushCanvasHistory(label: string) {
    canvasUndoRef.current = captureCanvasHistorySnapshot(label);
  }

  function restoreCanvasHistorySnapshot(snapshot: CanvasHistorySnapshot, gesture: string) {
    cancelTransientCanvasInteractions();
    const restoredNodes = snapshot.nodes.map(cloneWorkflowNode);
    const restoredGroups = snapshot.layoutGroups.map((group) => ({ ...group, memberNodeIds: [...group.memberNodeIds] }));
    nodesRef.current = restoredNodes;
    layoutGroupsRef.current = restoredGroups;
    setNodes(restoredNodes);
    setLayoutGroups(restoredGroups);
    commitNodeSelection(
      reduceNodeSelection(snapshot.selection, { type: "replace-group", ids: snapshot.selection.ids, primaryId: snapshot.selection.primaryId }, new Set(restoredNodes.map((node) => node.id))),
      gesture
    );
    setCanvasMenu(null);
  }

  function undoCanvasCommand() {
    const snapshot = canvasUndoRef.current;
    if (!snapshot) return false;
    canvasUndoRef.current = null;
    restoreCanvasHistorySnapshot(snapshot, "undo");
    addEvent(`撤销：${snapshot.label}`);
    return true;
  }

  function trimIdentityMap<T>(map: Map<string, T>, limit = 192) {
    while (map.size > limit) {
      const oldest = map.keys().next().value;
      if (typeof oldest !== "string") break;
      map.delete(oldest);
    }
  }

  function rememberCompletedLocalToolOperation(operationId: string) {
    completedLocalToolOperationsRef.current.add(operationId);
    while (completedLocalToolOperationsRef.current.size > 192) {
      const oldest = completedLocalToolOperationsRef.current.values().next().value;
      if (typeof oldest !== "string") break;
      completedLocalToolOperationsRef.current.delete(oldest);
    }
  }

  function clearLocalToolTimelineScope() {
    cancelAgentStreamFlush();
    pendingAgentStreamMessagesRef.current.clear();
    toolTimelineAliasesRef.current.clear();
    pendingImageToolResultsRef.current.clear();
    pendingImageToolSettlementsRef.current.clear();
    completedLocalToolOperationsRef.current.clear();
    renderedLocalToolOperationsRef.current.clear();
    imageToolCommitEvidenceRef.current.clear();
    pendingLayerNarrationRunIdsRef.current.clear();
    setStreamingImagePreviews({});
    lastTimelineMessageRef.current = "";
  }

  function cancelAgentStreamFlush() {
    if (agentStreamFlushTimerRef.current === null) return;
    window.clearTimeout(agentStreamFlushTimerRef.current);
    agentStreamFlushTimerRef.current = null;
  }

  function flushPendingAgentStreamMessages() {
    cancelAgentStreamFlush();
    const pending = [...pendingAgentStreamMessagesRef.current.values()];
    if (pending.length === 0) return;
    pendingAgentStreamMessagesRef.current.clear();
    setMessages((current) => pending.reduce(
      (nextMessages, message) => appendStreamingAgentMessage(nextMessages, message),
      current
    ));
  }

  function queueAgentStreamMessage(message: AgentMessage) {
    const current = pendingAgentStreamMessagesRef.current.get(message.id);
    pendingAgentStreamMessagesRef.current.set(message.id, current
      ? {
          ...current,
          ...message,
          content: `${current.content || ""}${message.content || ""}`
        }
      : message);
    if (agentStreamFlushTimerRef.current === null) {
      agentStreamFlushTimerRef.current = window.setTimeout(flushPendingAgentStreamMessages, 32);
    }
  }

  function recordImageToolCommitEvidence(operationId: string, patch: Partial<ImageToolCommitEvidence>) {
    if (!NAIMAGE_AIDEBUG_RUNTIME_ENABLED) return;
    const id = String(operationId || "").trim();
    if (!id) return;
    const current = imageToolCommitEvidenceRef.current.get(id);
    imageToolCommitEvidenceRef.current.set(id, {
      operationId: id,
      nodeIds: current?.nodeIds ?? [],
      ...current,
      ...patch,
      ...(current?.nodeCommitAt && patch.nodeCommitAt
        ? { nodeCommitAt: Math.min(current.nodeCommitAt, patch.nodeCommitAt) }
        : {}),
      ...(patch.nodeIds ? { nodeIds: [...patch.nodeIds] } : {})
    });
    trimIdentityMap(imageToolCommitEvidenceRef.current, 48);
  }

  function settleDeferredImageToolResult(
    requestedOperationId: string,
    outcome: { status: "done" | "error"; summary?: string; detail?: string },
    fallbackProgress?: AgentProgress
  ) {
    const operationId = String(requestedOperationId || "").trim();
    if (!operationId) return false;
    if (renderedLocalToolOperationsRef.current.has(operationId)) return true;
    const pending = pendingImageToolResultsRef.current.get(operationId) ?? fallbackProgress ?? {
      runId: operationId,
      phase: outcome.status === "error" ? "tool-error" : "tool-done",
      tool: "image_gen",
      operationId,
      toolRunId: operationId,
      operation: "layers",
      input: { operation: "layers" },
      summary: outcome.summary || (outcome.status === "error" ? "分层 PNG 本地处理失败。" : "分层 PNG 已完成。"),
      detail: outcome.detail,
      createdAt: new Date().toISOString()
    };

    const settledProgress: AgentProgress = {
      ...pending,
      phase: outcome.status === "error" ? "tool-error" : "tool-done",
      operationId,
      toolRunId: operationId,
      summary: outcome.summary || pending.summary,
      detail: outcome.detail ?? pending.detail,
      createdAt: new Date().toISOString()
    };
    const trace = toolTraceForProgress(settledProgress);
    if (!trace) return false;
    const toolRunKey = operationId.replace(/[^a-zA-Z0-9_-]+/g, "-").slice(0, 96);
    const startId = `progress-tool-${toolRunKey}-start`;
    const resultId = `progress-tool-${toolRunKey}-result`;
    const isError = outcome.status === "error";
    const settledOperation = progressInputOperation(settledProgress) || String(settledProgress.operation || "");
    recordImageToolCommitEvidence(operationId, {
      operation: settledOperation,
      resultCardScheduledAt: Date.now(),
      ...(isError ? { error: outcome.summary || "图片任务执行失败。" } : {})
    });
    setMessages((current) => {
      const resultIndex = current.findIndex((message) => message.id === resultId);
      const resultMessage: AgentMessage = {
        id: resultId,
        role: "assistant",
        content: "",
        createdAt: resultIndex >= 0 ? current[resultIndex].createdAt : nowLabel(),
        status: isError ? "error" : "done",
        meta: "progress",
        toolTrace: {
          ...trace,
          stage: "result",
          operationId,
          brief: "",
          prompts: undefined,
          completionText: trace.completionText || (isError ? "执行失败" : "图片生成完成")
        }
      };
      const settled = current.map((message) => message.id === startId
        ? { ...message, status: (isError ? "error" : "done") as AgentMessage["status"] }
        : message);
      if (resultIndex < 0) return [...settled, resultMessage].slice(-120);
      return settled.map((message) => message.id === resultId ? resultMessage : message).slice(-120);
    });
    setAgentProgress((current) => [...current, settledProgress].slice(-48));
    pendingImageToolResultsRef.current.delete(operationId);
    rememberCompletedLocalToolOperation(operationId);
    renderedLocalToolOperationsRef.current.add(operationId);
    while (renderedLocalToolOperationsRef.current.size > 192) {
      const oldest = renderedLocalToolOperationsRef.current.values().next().value;
      if (typeof oldest !== "string") break;
      renderedLocalToolOperationsRef.current.delete(oldest);
    }
    scheduleAgentFeedBottomSettle();
    return true;
  }

  function startLocalImageTimeline(progress: AgentProgress, requestMessage: AgentMessage) {
    const operationId = String(progress.operationId || progress.toolRunId || "").trim();
    const trace = toolTraceForProgress(progress);
    if (!operationId || !trace) return false;
    const toolRunKey = operationId.replace(/[^a-zA-Z0-9_-]+/g, "-").slice(0, 96);
    const startId = `progress-tool-${toolRunKey}-start`;
    pendingImageToolResultsRef.current.set(operationId, progress);
    trimIdentityMap(pendingImageToolResultsRef.current, 48);
    const startMessage: AgentMessage = {
      id: startId,
      role: "assistant",
      content: "",
      createdAt: nowLabel(),
      status: "running",
      meta: "progress",
      toolTrace: { ...trace, stage: "start", operationId }
    };
    setMessages((current) => [
      ...current.filter((message) => message.id !== startId && message.id !== requestMessage.id),
      requestMessage,
      startMessage
    ].slice(-120));
    setAgentProgress((current) => [...current, progress].slice(-48));
    scheduleAgentFeedBottomSettle();
    return true;
  }

  async function waitForCanvasNodeCommit(nodeId: string, attempts = 120) {
    for (let attempt = 0; attempt < attempts; attempt += 1) {
      if (document.querySelector(`.flow-node[data-node-id="${CSS.escape(nodeId)}"]`)) return true;
      await new Promise<void>((resolve) => window.setTimeout(resolve, 25));
    }
    return false;
  }

  async function waitForCanvasImageCommit(nodeId: string) {
    let element: HTMLElement | null = null;
    for (let attempt = 0; attempt < 120; attempt += 1) {
      element = document.querySelector<HTMLElement>(`.flow-node[data-node-id="${CSS.escape(nodeId)}"]`);
      if (element) break;
      await new Promise<void>((resolve) => window.setTimeout(resolve, 25));
    }
    const expectedRendered = renderedNodesRef.current.some((node) => node.id === nodeId);
    if (!element) {
      return {
        visible: false,
        previewReady: false,
        expectedRendered,
        settleReason: expectedRendered ? "visibility-timeout" as const : "virtualized" as const
      };
    }

    const preview = element.querySelector<HTMLImageElement>(".node-image-preview img");
    if (!preview) {
      return { visible: true, previewReady: false, expectedRendered, settleReason: "node-visible" as const };
    }
    const isReady = () => preview.complete && preview.naturalWidth > 0 && preview.naturalHeight > 0;
    if (!isReady()) {
      await new Promise<void>((resolve) => {
        let settled = false;
        const finish = () => {
          if (settled) return;
          settled = true;
          window.clearTimeout(timer);
          preview.removeEventListener("load", finish);
          preview.removeEventListener("error", finish);
          resolve();
        };
        const timer = window.setTimeout(finish, 1_200);
        preview.addEventListener("load", finish, { once: true });
        preview.addEventListener("error", finish, { once: true });
        void preview.decode?.().then(finish, finish);
      });
    }
    return {
      visible: true,
      previewReady: isReady(),
      expectedRendered,
      settleReason: isReady() ? "preview-ready" as const : "node-visible" as const
    };
  }

  function scheduleImageToolResultAfterCanvasCommit(operationId: string, progress: AgentProgress) {
    const id = String(operationId || "").trim();
    if (!id || pendingImageToolSettlementsRef.current.has(id) || renderedLocalToolOperationsRef.current.has(id)) return;
    pendingImageToolSettlementsRef.current.add(id);
    while (pendingImageToolSettlementsRef.current.size > 48) {
      const oldest = pendingImageToolSettlementsRef.current.values().next().value;
      if (typeof oldest !== "string") break;
      pendingImageToolSettlementsRef.current.delete(oldest);
    }
    void (async () => {
      try {
        let committedNodeId = "";
        for (let attempt = 0; attempt < 120; attempt += 1) {
          await new Promise<void>((resolve) => window.setTimeout(resolve, 25));
          const candidateId = agentToolNodeIdsRef.current[id] || "";
          const candidate = candidateId ? nodesRef.current.find((node) => node.id === candidateId) : undefined;
          if (!candidate || candidate.imageState === "generating") continue;
          committedNodeId = candidate.id;
          break;
        }
        if (!committedNodeId) {
          recordImageToolCommitEvidence(id, {
            operation: progressInputOperation(progress) || String(progress.operation || ""),
            settleReason: "commit-only",
            visibilityTimedOut: true,
            error: "图片结果已返回，但画布成果未在 3 秒内提交。"
          });
          settleDeferredImageToolResult(id, { status: "done", summary: progress.summary, detail: typeof progress.detail === "string" ? progress.detail : undefined }, progress);
          return;
        }
        const committedAt = Date.now();
        recordImageToolCommitEvidence(id, {
          operation: progressInputOperation(progress) || String(progress.operation || ""),
          nodeCommitAt: committedAt,
          nodeIds: [committedNodeId]
        });
        const readiness = await waitForCanvasImageCommit(committedNodeId);
        recordImageToolCommitEvidence(id, {
          expectedRendered: readiness.expectedRendered,
          ...(readiness.visible ? { nodeVisibleAt: Date.now() } : {}),
          ...(readiness.previewReady ? { previewReadyAt: Date.now() } : {}),
          settleReason: readiness.settleReason,
          visibilityTimedOut: readiness.settleReason === "visibility-timeout"
        });
        settleDeferredImageToolResult(id, { status: "done", summary: progress.summary, detail: typeof progress.detail === "string" ? progress.detail : undefined }, progress);
      } finally {
        pendingImageToolSettlementsRef.current.delete(id);
      }
    })();
  }

  function upsertStreamingImagePreview(payload: AgentProgress, operationId: string) {
    const requestIndex = Math.max(1, Math.floor(Number(payload.partialImage?.requestIndex || 1) || 1));
    cancelStreamingImagePreviewClear(operationId, "", requestIndex);
    setStreamingImagePreviews((current) => upsertStreamingImagePreviewState(current, payload, operationId));
  }

  function cancelStreamingImagePreviewClear(operationId: string, runId = "", requestIndex?: number) {
    const pending = streamingPreviewClearFramesRef.current;
    for (const [key, scheduled] of pending) {
      const scopeMatches = operationId
        ? scheduled.operationId === operationId
        : runId
          ? scheduled.runId === runId
          : true;
      if (!scopeMatches) continue;
      if (requestIndex && scheduled.requestIndex && scheduled.requestIndex !== requestIndex) continue;
      window.cancelAnimationFrame(scheduled.frame);
      pending.delete(key);
    }
  }

  function clearStreamingImagePreview(operationId: string, runId = "", requestIndex?: number) {
    const clearKey = `${operationId || `run:${runId || "all"}`}:${requestIndex || "*"}`;
    cancelStreamingImagePreviewClear(operationId, runId, requestIndex);
    const frame = window.requestAnimationFrame(() => {
      streamingPreviewClearFramesRef.current.delete(clearKey);
      setStreamingImagePreviews((current) => {
        const entries = Object.entries(current).filter(([, preview]) => {
          if (operationId && preview.operationId === operationId) {
            return requestIndex ? preview.requestIndex !== requestIndex : false;
          }
          if (!operationId && runId && preview.runId === runId) return false;
          return true;
        });
        return entries.length === Object.keys(current).length ? current : Object.fromEntries(entries);
      });
    });
    streamingPreviewClearFramesRef.current.set(clearKey, { frame, operationId, runId, requestIndex });
  }

  const bindCanvasRef = useCallback((element: HTMLDivElement | null) => {
    if (lastCanvasElementRef.current === element) return;
    lastCanvasElementRef.current = element;
    canvasRef.current = element;
    setCanvasMountTick((current) => current + 1);
  }, []);

  useEffect(() => {
    if (!fileMenuOpen && !projectMenuOpen && !settingsOpen && !accountOpen) return;

    function closeTransientSurfaces(event: PointerEvent) {
      const target = event.target instanceof Element ? event.target : null;
      if (!target) return;
      if (fileMenuOpen && !target.closest(".file-command-menu")) setFileMenuOpen(false);
      if (projectMenuOpen && !target.closest(".project-menu:not(.file-command-menu)")) setProjectMenuOpen(false);
      if (settingsOpen && !target.closest(".settings-drawer, .model-config-dialog, .agent-text-editor-dialog, .app-settings-button, [data-ui-surface-layer]")) setSettingsOpen(false);
      if (accountOpen && !target.closest(".account-drawer, .account-avatar-button, [data-ui-surface-layer]")) setAccountOpen(false);
    }

    document.addEventListener("pointerdown", closeTransientSurfaces, true);
    return () => document.removeEventListener("pointerdown", closeTransientSurfaces, true);
  }, [accountOpen, fileMenuOpen, projectMenuOpen, settingsOpen]);

  useEffect(() => {
    if (!assetContextMenu) return;
    const closeAssetMenu = (event: PointerEvent) => {
      const target = event.target instanceof Element ? event.target : null;
      if (target?.closest(".asset-context-menu")) return;
      setAssetContextMenu(null);
    };
    const closeOnBlur = () => setAssetContextMenu(null);
    document.addEventListener("pointerdown", closeAssetMenu, true);
    window.addEventListener("blur", closeOnBlur);
    return () => {
      document.removeEventListener("pointerdown", closeAssetMenu, true);
      window.removeEventListener("blur", closeOnBlur);
    };
  }, [assetContextMenu]);

// -----------------------------------------------------------------------------
// MAIN 10B Boot, Persistence, And Bridge Effects
// -----------------------------------------------------------------------------

  function resetProjectNodeMutationTracking(projectId: string, session: StudioWorkflowSession) {
    if (!projectId) return;
    projectNodeMutationJournalRef.current[projectId] = [...(session.nodeMutationJournal ?? [])];
    projectNodeMutationWriterCheckpointsRef.current[projectId] = [...(session.nodeMutationWriterCheckpoints ?? [])];
    projectNodeMutationBarriersRef.current[projectId] = [...(session.nodeMutationBarriers ?? [])];
    projectNodeMutationBaselineRef.current[projectId] = session.nodes.map(cloneWorkflowNode);
  }

  async function persistProjectSessionNow(projectId: string, snapshot: StudioWorkflowSession) {
    if (!projectId) throw new Error("请先创建或打开项目，再保存画布。");
    const flushStartedAt = performance.now();
    try {
      const currentRevision = Math.max(0, Math.floor(Number(projectSessionRevisionRef.current[projectId] ?? snapshot.sessionRevision ?? 0) || 0));
      const requestedRevision = currentRevision + 1;
      const journaledSnapshot = {
        ...snapshot,
        schemaVersion: 5,
        nodeMutationJournal: projectNodeMutationJournalRef.current[projectId] ?? snapshot.nodeMutationJournal ?? [],
        nodeMutationWriterCheckpoints: projectNodeMutationWriterCheckpointsRef.current[projectId] ?? snapshot.nodeMutationWriterCheckpoints ?? [],
        nodeMutationBarriers: projectNodeMutationBarriersRef.current[projectId] ?? snapshot.nodeMutationBarriers ?? []
      };
      projectSessionRevisionRef.current[projectId] = requestedRevision;
      const result = await saveSessionToStore({
        ...journaledSnapshot,
        projectId,
        sessionRevision: requestedRevision
      }, {
        revision: requestedRevision,
        nodeMutation: {
          writerId: RENDERER_PERSISTENCE_ORIGIN_ID,
          observedRevision: currentRevision,
          baselineNodes: projectNodeMutationBaselineRef.current[projectId] ?? []
        }
      });
      if (!result?.ok) throw new Error(result?.error || "保存项目会话失败。");
      const appliedRevision = Math.max(requestedRevision, Math.floor(Number(result.appliedRevision ?? requestedRevision) || requestedRevision));
      projectSessionRevisionRef.current[projectId] = Math.max(projectSessionRevisionRef.current[projectId] ?? 0, appliedRevision);
      projectNodeMutationJournalRef.current[projectId] = result.nodeMutationJournal ?? journaledSnapshot.nodeMutationJournal;
      projectNodeMutationWriterCheckpointsRef.current[projectId] = result.nodeMutationWriterCheckpoints ?? journaledSnapshot.nodeMutationWriterCheckpoints;
      projectNodeMutationBarriersRef.current[projectId] = result.nodeMutationBarriers ?? journaledSnapshot.nodeMutationBarriers;
      projectNodeMutationBaselineRef.current[projectId] = snapshot.nodes.map(cloneWorkflowNode);
      if (NAIMAGE_RUNTIME_METRICS) {
        const durationMs = Math.max(0, performance.now() - flushStartedAt);
        const metrics = persistenceDebugMetricsRef.current;
        metrics.lastFlushMs = durationMs;
        metrics.totalFlushMs += durationMs;
        metrics.maxFlushMs = Math.max(metrics.maxFlushMs, durationMs);
        if (result.applied === false || result.skippedStale) metrics.skippedWriteCount += 1;
        else metrics.writeCount += 1;
      }
      return result;
    } catch (error) {
      if (NAIMAGE_RUNTIME_METRICS) {
        const durationMs = Math.max(0, performance.now() - flushStartedAt);
        const metrics = persistenceDebugMetricsRef.current;
        metrics.failedWriteCount += 1;
        metrics.lastFlushMs = durationMs;
        metrics.totalFlushMs += durationMs;
        metrics.maxFlushMs = Math.max(metrics.maxFlushMs, durationMs);
      }
      throw error;
    }
  }

  async function persistProjectSession(projectId: string, snapshot: StudioWorkflowSession) {
    const previous = projectSessionPersistQueueRef.current[projectId] ?? Promise.resolve();
    const task = previous
      .catch(() => undefined)
      .then(() => persistProjectSessionNow(projectId, snapshot));
    projectSessionPersistQueueRef.current[projectId] = task;
    try {
      return await task;
    } finally {
      if (projectSessionPersistQueueRef.current[projectId] === task) {
        delete projectSessionPersistQueueRef.current[projectId];
      }
    }
  }

