        const targetHighlighted = Boolean(targetNodeElement?.classList.contains("asset-drop-target"));
        const endPointEvidence = pointEvidence(clientX, clientY);
        sourceNodeElement.dispatchEvent(new PointerEvent("pointerup", {
          bubbles: true,
          cancelable: true,
          pointerId,
          pointerType: "mouse",
          isPrimary: true,
          button: 0,
          buttons: 0,
          clientX,
          clientY
        }));
        const stateWait = await waitForDebugState(
          "pointer-image-layout-grouped",
          (state) => Boolean(
            state.nodes?.some((node) => node.id === sourceNodeId) &&
            state.nodes?.some((node) => node.id === targetContainerId) &&
            state.layoutGroups?.some((group) => group.hostNodeId === targetContainerId && group.memberNodeIds.includes(sourceNodeId))
          ),
          6000
        );
        const targetAfter = nodesRef.current.find((node) => node.id === targetContainerId);
        const afterRead = await window.naimageConfig?.readAssetDataUrl?.({ path: asset.path });
        const sourceStillPresent = nodesRef.current.some((node) => node.id === sourceNodeId);
        const layoutGroup = layoutGroupsRef.current.find((group) => group.hostNodeId === targetContainerId && group.memberNodeIds.includes(sourceNodeId));
        const groupedNodes = layoutGroup?.memberNodeIds.map((id) => nodesRef.current.find((node) => node.id === id)).filter((node): node is WorkflowNode => Boolean(node)) ?? [];
