        const sourceBytesUnchanged = Boolean(beforeRead?.ok && afterRead?.ok && beforeRead.dataUrl && beforeRead.dataUrl === afterRead.dataUrl);
        const viewerSuppressed = !document.querySelector(".image-viewer");
        const dropHighlightCleared = !document.querySelector(".flow-node.asset-drop-target");
        const routeCompleted = Boolean(stateWait.ok && layoutGroup);
        const afterEvidence = relevantStateEvidence();
