      const name = String(payload?.name || "").trim();
      if (!name) return { ok: false, error: "缺少工具名称。", state: readDebugState() };
      if (!window.naimageAgent?.runTool) return { ok: false, error: "Agent runtime bridge unavailable.", state: readDebugState() };
      const runtimeProjection = projectCanvasImageLayouts(nodesRef.current, layoutGroupsRef.current);
      const runtimeNodes = runtimeProjection.canvasNodes;
      const selectedId = payload.selectedNodeId ?? selectedNodeIdRef.current;
      const selectedIds = selectedId ? [selectedId] : [];
      const scopedNodes = selectedIds
        .map((id) => runtimeProjection.canvasNodeById.get(runtimeProjection.groupByMember.get(id)?.hostNodeId ?? id))
        .filter((node): node is WorkflowNode => Boolean(node));
