    const debugProbeImageDataUrl = (index: number, label = "") => {
      const canvas = document.createElement("canvas");
      canvas.width = 128;
      canvas.height = 128;
      const context = canvas.getContext("2d");
      if (!context) return "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAYAAABytg0kAAAAGklEQVR4nGP8z8Dwn4GBgYGJAQkwMaACDAwAFwICBXS9U/8AAAAASUVORK5CYII=";
      const palettes = [
        ["#0f4c5c", "#4cc9f0", "#f1faee"],
        ["#4a1942", "#f72585", "#ffd6ff"],
        ["#3a5a40", "#95d5b2", "#fefae0"],
        ["#5f370e", "#ff9f1c", "#fff3b0"],
        ["#253237", "#80ed99", "#c7f9cc"]
      ];
      const palette = palettes[Math.abs(index) % palettes.length];
      context.fillStyle = palette[0];
      context.fillRect(0, 0, 128, 128);
      context.fillStyle = palette[1];
      context.beginPath();
      context.arc(36 + (index % 3) * 22, 42 + (index % 2) * 14, 19, 0, Math.PI * 2);
      context.fill();
      context.fillStyle = palette[2];
      context.beginPath();
      context.moveTo(12, 112);
      context.lineTo(52 + (index % 4) * 10, 64);
      context.lineTo(116, 112);
      context.closePath();
      context.fill();
      context.fillStyle = "rgba(0, 0, 0, 0.62)";
      context.fillRect(82, 10, 36, 26);
      context.fillStyle = "#ffffff";
      context.font = "700 16px Segoe UI, sans-serif";
      context.textAlign = "center";
      context.textBaseline = "middle";
      context.fillText(String(index + 1), 100, 23);
      if (label) {
        context.fillStyle = "rgba(0, 0, 0, 0.54)";
        context.fillRect(8, 88, 54, 24);
        context.fillStyle = "#ffffff";
        context.font = "700 12px Segoe UI, sans-serif";
        context.fillText(label.slice(0, 4), 35, 100);
      }
      return canvas.toDataURL("image/png");
    };
