      if (!target?.layerGroup) return { ok: false, error: "debug layer node not found", state: readDebugState() };
      const mode: LayerViewerState["mode"] = payload?.mode === "solo" || payload?.mode === "onion" ? payload.mode : "composite";
      openLayerGroupViewer(target.id, mode);
      let viewer: HTMLElement | null = null;
