      const requestedTotal = clamp(Number.isFinite(explicitTotal) && explicitTotal > 0 ? explicitTotal : 15, 1, 30);
      const requestedAgent = clamp(Number(payload?.agentCount ?? Math.min(10, requestedTotal)), 0, 30);
      const requestedDirectDefault = Math.max(0, requestedTotal - requestedAgent);
      const requestedDirect = clamp(Number(payload?.directCount ?? requestedDirectDefault), 0, 30);
      let agentCount = Math.min(requestedAgent, requestedTotal);
      let directCount = Math.min(requestedDirect, Math.max(0, requestedTotal - agentCount));
      const missingCount = requestedTotal - agentCount - directCount;
      if (missingCount > 0) directCount = Math.min(30 - agentCount, directCount + missingCount);
      if (agentCount + directCount <= 0) directCount = requestedTotal;
