  async function runManualImageTask(
    task: ImageTaskDraft,
    options?: { targetNodeId?: string; forkFromNodeId?: string; worldX?: number; worldY?: number; quotaChecked?: boolean; append?: boolean; requestedCount?: number; targetTotal?: number }
  ) {
    if (!activeProjectIdRef.current) {
      setServerMessage("请先创建或打开项目，再生成图片。");
      return;
    }
    if (!activeConversationIdRef.current) {
      setServerMessage("请先创建或选择一个对话，再生成图片。");
      return;
    }
    if (agentExecutionBusyNow()) {
      setServerMessage("Agent 正在执行当前任务，新的图片任务没有被重复提交。");
      return;
    }
    if (!serverUser) {
      setServerMessage("请先登录后再生成图片。");
      return;
    }
    if (!window.naimageServer?.generateImage) {
      setServerMessage("本地账户服务正在启动或连接失败。");
      return;
    }
    const imageServer = window.naimageServer;
    const requestProjectId = activeProjectIdRef.current;
    const requestConversationId = activeConversationIdRef.current;
    const taskSnapshot = cloneImageTaskDraft(task);
    const hasRequestedWorldPosition = Number.isFinite(options?.worldX) && Number.isFinite(options?.worldY);
    const frozenTargetNode = options?.targetNodeId ? nodesRef.current.find((item) => item.id === options.targetNodeId) : null;
    const frozenForkNodeId = options?.forkFromNodeId || (!hasRequestedWorldPosition ? selectedNodeIdRef.current : "");
    const frozenForkNode = frozenForkNodeId ? nodesRef.current.find((item) => item.id === frozenForkNodeId) : null;
    const nodeExecutionFingerprint = (node: WorkflowNode | null | undefined) => node ? {
      id: node.id,
      type: node.type,
      status: node.status,
      imageState: node.imageState,
      generationRunId: node.generationRunId,
      assets: (node.assets ?? []).map((asset, index) => ({
        assetId: asset.assetId,
        occurrenceId: asset.occurrenceId,
        contentHash: asset.contentHash,
        path: asset.path,
        relativePath: asset.relativePath,
        index: asset.index ?? index + 1
      }))
    } : null;
    const taskExecutionSignature = (
      value: ImageTaskDraft,
      target: WorkflowNode | null | undefined,
      fork: WorkflowNode | null | undefined,
    ) => JSON.stringify({
      task: cloneImageTaskDraft(value),
      options: {
        targetNodeId: options?.targetNodeId || "",
        forkFromNodeId: frozenForkNodeId,
        worldX: Number.isFinite(options?.worldX) ? Number(options?.worldX) : null,
        worldY: Number.isFinite(options?.worldY) ? Number(options?.worldY) : null,
        append: options?.append === true,
        requestedCount: Number(options?.requestedCount ?? 0),
        targetTotal: Number(options?.targetTotal ?? 0)
      },
      target: nodeExecutionFingerprint(target),
      fork: nodeExecutionFingerprint(fork)
    });
    const executionScope: AgentExecutionScopeSnapshot = {
      projectId: requestProjectId,
      conversationId: requestConversationId,
      taskSignature: taskExecutionSignature(taskSnapshot, frozenTargetNode, frozenForkNode)
    };
    const reservationId = uid("reservation");
    let reservationOwned = false;
    commitExecutionReservation(reservationId);
    try {
      if (!options?.quotaChecked && await blockImageTaskIfQuotaInsufficient(taskSnapshot)) return;
    } finally {
      reservationOwned = executionReservationRef.current === reservationId;
      if (reservationOwned) commitExecutionReservation(null);
    }

    const targetNode = options?.targetNodeId ? nodesRef.current.find((item) => item.id === options.targetNodeId) : null;
    const forkNode = frozenForkNodeId ? nodesRef.current.find((item) => item.id === frozenForkNodeId) : null;
    const currentTaskSignature = taskExecutionSignature(task, targetNode, forkNode);
    if (!reservationOwned) return;
    if (!agentExecutionScopeMatches(executionScope, currentExecutionScope(currentTaskSignature))) {
      setServerMessage("画布、会话或任务素材已在额度检查期间变化，本次生图没有提交；请在当前状态重新执行。");
      return;
    }
    if (targetNode && imageRunStartsRef.current[targetNode.id]) {
      setServerMessage("这个节点正在生成中，可以先停止或等待完成。");
      return;
    }
    const parentId = targetNode ? targetNode.parentId : forkNode?.id;
    const id = targetNode?.id ?? nextManualImageNodeId();
    const generationRunId = uid("gen");
    const startedAt = Date.now();
    const nodePrompt = taskSnapshot.prompt;
    taskSnapshot.count = clamp(Number(options?.requestedCount ?? taskSnapshot.count), 1, 10);
    taskSnapshot.batchMode = "parallel";
    taskSnapshot.model = taskSnapshot.model || settings.imageModel || "";
    const size = sizeFromDraft(taskSnapshot, settings);
    const existingAssets = options?.append && targetNode ? cloneImageAssets(targetNode.assets) : [];
    const total =
      options?.append && targetNode
        ? clamp(Number(options.targetTotal ?? Math.max(targetNode.imageProgress?.total ?? targetNode.imageParams?.count ?? taskSnapshot.count, existingAssets.length + taskSnapshot.count)), 1, 10)
        : taskSnapshot.count;
    const startCompleted = existingAssets.length;
    const remainingCount = Math.max(0, total - startCompleted);
    const initialNodeSize = displaySizeForImageNode(size, Math.max(total, 1));
    const clampedInitialNodeSize = clampImageNodeDimensions(
      size,
      Math.max(total, 1),
      targetNode?.width ?? initialNodeSize.width,
      targetNode?.height ?? initialNodeSize.height
    );
    const requestedPosition = hasRequestedWorldPosition
      ? clampNodeWorldPosition(
          { x: Number(options?.worldX), y: Number(options?.worldY) },
          clampedInitialNodeSize.width,
          clampedInitialNodeSize.height
        )
      : null;
    const openPosition = requestedPosition && !targetNode
      ? findOpenWorkflowNodePosition(nodesRef.current, {
          width: clampedInitialNodeSize.width,
          height: clampedInitialNodeSize.height,
          preferredX: requestedPosition.x,
          preferredY: requestedPosition.y
        })
      : null;
    const initialImageCollection = parallelImageCollection(id, total, existingAssets, taskSnapshot.prompt, targetNode?.imageCollection);
    const nodeBase: WorkflowNode = {
      id,
      title: "生成图片",
      prompt: nodePrompt,
      type: "image",
      status: "working",
      x: targetNode?.x ?? openPosition?.x ?? (forkNode?.x ?? 120) + 300,
      y: targetNode?.y ?? openPosition?.y ?? (forkNode?.y ?? 160) + 110,
      parentId,
      branch: "basic",
      outputs: existingAssets.length,
      createdAt: targetNode?.createdAt ?? nowLabel(),
      assets: existingAssets,
      imageContainerSpec: cloneImageContainerSpec(targetNode?.imageContainerSpec),
      imageCollection: initialImageCollection,
      imageState: remainingCount > 0 ? "generating" : "done",
      imageError: undefined,
      imageParams: cloneImageTaskDraft({ ...taskSnapshot, size, count: total, batchMode: "parallel", referenceImages: taskSnapshot.referenceImages ?? [] }),
      imageProgress: imageProgressState(
        total,
        startCompleted,
        remainingCount > 1 ? `按每批 ${settings.imageBatchSize} 路顺序生成 ${remainingCount} 张` : `准备生成 ${remainingCount} 张`
      ),
      generationRunId,
      ...clampedInitialNodeSize
    };
    const node = withGeneratedImageContentPresentation(nodeBase, initialImageCollection, targetNode);
    setNodes((current) => (targetNode
      ? current.map((item) => (item.id === id ? { ...item, ...node, zOrder: item.zOrder ?? node.zOrder ?? nextNodeZOrder(current) } : item))
      : [...current, { ...node, zOrder: nextNodeZOrder(current) }]
    ));
    setSelectedNodeId(id);
    setActiveNodeId(id);
    agentToolNodeIdsRef.current[generationRunId] = id;
    markImageRunStarted(id, startedAt);
    setAgentStatus("editing");
    setActiveRunStartedAt(startedAt);
    setRunElapsedSeconds(0);
    const manualReferences = taskSnapshot.referenceImages ?? [];
    const manualRequestMessage: AgentMessage = {
      id: `manual-user-${generationRunId}`,
      role: "user",
      content: nodePrompt,
      createdAt: nowLabel(),
      status: "done",
      meta: "human / canvas",
      ...(manualReferences.length ? {
        attachments: {
          referenceAssets: manualReferences.map((reference, index): TaskAssetReference => ({
            assetId: reference.assetId || stableImageAssetId(reference, index + 1),
            displayCode: reference.displayCode || `REF${index + 1}`,
            role: "reference",
            name: reference.name || `参考图 ${index + 1}`,
            path: reference.path,
            relativePath: reference.relativePath,
            assetUrl: reference.assetUrl,
            contentHash: reference.contentHash
          })),
          referenceCount: manualReferences.length
        }
      } : {})
    };
    startLocalImageTimeline({
      runId: generationRunId,
      projectId: requestProjectId,
      conversationId: requestConversationId,
      phase: "image-request",
      tool: "image_gen",
      operationId: generationRunId,
      toolRunId: generationRunId,
      operation: "generate",
      brief: total > 1 ? `按每批 ${settings.imageBatchSize} 路顺序生成 ${total} 张图片。` : "按画布设置生成一张图片。",
      params: `${taskSnapshot.ratio} · ${taskSnapshot.resolution} · ${qualityLabel(taskSnapshot.quality)} · ${total} 张 · ${manualReferences.length} 张参考图`,
      input: {
        operation: "generate",
        prompt: nodePrompt,
        ratio: taskSnapshot.ratio,
        resolution: taskSnapshot.resolution,
        size,
        quality: taskSnapshot.quality,
        count: total,
        model: taskSnapshot.model,
        referenceCount: manualReferences.length
      },
      summary: `画布已接纳节点 ${id}，准备生成 ${remainingCount} 张。`,
      createdAt: new Date().toISOString()
    }, manualRequestMessage);

    try {
      const assetSlots: (ImageAsset | null)[] = Array.from({ length: total }, (_item, index) => existingAssets[index] ?? null);
      const errors: string[] = [];
      const failedSlots = new Set<number>();

      async function generateSlot(index: number) {
        if (imageRunStartsRef.current[id] === undefined) return;
        setNodes((current) =>
          current.map((item) =>
            item.id === id && item.generationRunId === generationRunId
              ? {
                  ...item,
                  status: "working",
                  imageState: "generating",
                  imageError: undefined,
                  imageProgress: imageProgressState(total, assetSlots.filter(Boolean).length, "并行生成中", {
                    failed: failedSlots.size,
                    failedSlots: Array.from(failedSlots).sort((a, b) => a - b)
                  })
                }
              : item
          )
        );
        try {
          const attemptRunId = `${generationRunId}-${index + 1}`;
          const result = await imageServer.generateImage({
            runId: attemptRunId,
            operationId: generationRunId,
            requestIndex: index + 1,
            projectId: requestProjectId,
            conversationId: requestConversationId,
            nodeIds: [id],
            prompt: promptForIndependentImage(taskSnapshot.prompt, total, index),
            model: taskSnapshot.model || settings.imageModel,
            ratio: taskSnapshot.ratio,
            resolution: taskSnapshot.resolution,
            size,
            quality: taskSnapshot.quality,
            count: 1,
            referenceImages: taskSnapshot.referenceImages ?? [],
            outputFormat: taskSnapshot.outputFormat,
            outputCompression: taskSnapshot.outputCompression,
            background: taskSnapshot.background,
            moderation: taskSnapshot.moderation,
            inputFidelity: taskSnapshot.inputFidelity
          });
          if (imageRunStartsRef.current[id] === undefined || !executionScopeIsCurrent(executionScope)) return;
          if (!result.ok) {
            const quota = quotaBlockFromGenerateResult(taskSnapshot, result);
            if (quota) {
              setQuotaDialog(quota);
              setServerMessage(`余额不足，还差 ${yuan(quota.deficitCents)}。`);
              throw new Error("余额不足，本张生成失败；已返回的其他图片仍会保留。");
            }
            const upstreamParts = [
              typeof result.upstreamStatus === "number" ? `上游状态 ${result.upstreamStatus}` : "",
              result.upstreamErrorType ? `类型 ${result.upstreamErrorType}` : "",
              result.upstreamErrorCode ? `代码 ${result.upstreamErrorCode}` : "",
              result.upstreamErrorMessage && result.upstreamErrorMessage !== result.error ? result.upstreamErrorMessage : ""
            ].filter(Boolean);
            throw new Error(`${result.error ?? "生图失败。"}${upstreamParts.length ? `（${upstreamParts.join(" · ")}）` : ""}`);
          }
          const responseRunId = result.runId || attemptRunId;
          const nextAssets = (result.assets ?? [])
            .filter((asset) => !asset.runId || asset.runId === responseRunId)
            .map((asset) => ({ ...asset, index: index + 1, runId: responseRunId }));
          if (!nextAssets.length) throw new Error(`第 ${index + 1}/${total} 张返回无图片结果。`);
          assetSlots[index] = nextAssets[0];
          const assets = assetSlots.filter((asset): asset is ImageAsset => Boolean(asset));
          setNodes((current) =>
            current.map((item) =>
              item.id === id && item.generationRunId === generationRunId
                ? (() => {
                    const nodeSize = clampImageNodeDimensions(result.size ?? size, Math.max(total, assets.length), item.width, item.height);
                    const imageCollection = parallelImageCollection(id, total, assets, taskSnapshot.prompt, item.imageCollection, Array.from(failedSlots));
                    return withGeneratedImageContentPresentation({
                      ...item,
                      status: assets.length >= total ? "done" : "working",
                      outputs: assets.length,
                      assets: cloneImageAssets(assets),
                      imageState: assets.length >= total ? "done" : "generating",
                      imageError: undefined,
                      imageParams: cloneImageTaskDraft({ ...taskSnapshot, count: total, size, batchMode: "parallel", referenceImages: taskSnapshot.referenceImages ?? [] }),
                    imageProgress: imageProgressState(
                      total,
                      assets.length,
                      assets.length >= total ? `已完成 ${assets.length}/${total} 张` : `并行生成中，已完成 ${assets.length}/${total} 张`,
                      {
                        failed: failedSlots.size,
                        failedSlots: Array.from(failedSlots).sort((a, b) => a - b)
                      }
                    ),
                      generationRunId,
                      prompt: [
                        taskSnapshot.prompt,
                        "",
                        `model: ${result.model ?? settings.imageModel}`,
                        `size: ${result.size ?? size}`,
                        `quality: ${result.quality ?? taskSnapshot.quality}`,
                        `count: ${total}`,
                        `batchMode: parallel`,
                        `returned: ${assets.length}`,
                        ...(typeof result.costCents === "number" ? [`cost: ${yuan(result.costCents)}`] : [])
                      ].join("\n"),
                      ...nodeSize
                    }, imageCollection, item);
                  })()
                : item
            )
          );
          setAgentProgress((current) => [
            ...current,
            {
              runId: id,
              projectId: requestProjectId,
              conversationId: requestConversationId,
              phase: result.dryRun ? "image-dry-run" : "image-response",
              tool: "image_gen",
              summary: `节点 ${id} 已完成 ${assets.length}/${total} 张。`,
              detail: `${result.size ?? size} · ${qualityLabel(result.quality ?? taskSnapshot.quality)}`,
              createdAt: new Date().toISOString()
            }
          ].slice(-48));
        } catch (attemptError) {
          if (imageRunStartsRef.current[id] === undefined) return;
          const retryMessage = friendlyImageError(attemptError);
          errors.push(`第 ${index + 1} 张：${retryMessage}`);
          failedSlots.add(index + 1);
          const assets = assetSlots.filter((asset): asset is ImageAsset => Boolean(asset));
          const settledCount = assets.length + failedSlots.size;
          setNodes((current) =>
            current.map((item) =>
              item.id === id && item.generationRunId === generationRunId
                ? withGeneratedImageContentPresentation({
                    ...item,
                    status: settledCount >= total ? "review" : "working",
                    outputs: assets.length,
                    assets: cloneImageAssets(assets),
                    imageState: settledCount >= total ? (assets.length > 0 ? "done" : "error") : "generating",
                    imageError: retryMessage,
                  imageProgress: imageProgressState(
                    total,
                    assets.length,
                    settledCount >= total ? `部分失败，已完成 ${assets.length}/${total} 张` : `第 ${index + 1}/${total} 张失败，其他图片继续生成`,
                    {
                      failed: failedSlots.size,
                      failedSlots: Array.from(failedSlots).sort((a, b) => a - b),
                      activeIndex: settledCount >= total ? undefined : settledCount + 1
                    }
                  )
                  }, parallelImageCollection(id, total, assets, taskSnapshot.prompt, item.imageCollection, Array.from(failedSlots)), item)
                : item
            )
          );
          setAgentProgress((current) => [
            ...current,
            {
              runId: id,
              projectId: requestProjectId,
              conversationId: requestConversationId,
              phase: "image-error",
              tool: "image_gen",
              summary: retryMessage,
              detail: "这张失败，不自动重试；其他图片继续生成。",
              createdAt: new Date().toISOString()
            }
          ].slice(-48));
        } finally {
          clearStreamingImagePreview(generationRunId, "", index + 1);
        }
      }

      const slotIndexes = Array.from({ length: remainingCount }, (_item, offset) => startCompleted + offset);
      const batchSize = clamp(Math.round(Number(settings.imageBatchSize) || 3), 1, 10);
      for (let start = 0; start < slotIndexes.length; start += batchSize) {
        if (imageRunStartsRef.current[id] === undefined) break;
        const batch = slotIndexes.slice(start, start + batchSize);
        await Promise.all(batch.map((index) => generateSlot(index)));
      }
      if (!executionScopeIsCurrent(executionScope)) return;
      const assets = assetSlots.filter((asset): asset is ImageAsset => Boolean(asset));
      const completedAll = assets.length >= total && errors.length === 0;
      const stopped = imageRunStartsRef.current[id] === undefined && !completedAll;
      const durationSeconds = recordImageGenerationDuration(startedAt);
      setNodes((current) =>
        current.map((item) =>
          item.id === id && item.generationRunId === generationRunId
            ? withGeneratedImageContentPresentation({
                ...item,
                status: stopped || !completedAll ? "review" : "done",
                outputs: assets.length,
                assets: cloneImageAssets(assets),
                imageState: errors.length > 0 && assets.length === 0 ? "error" : assets.length > 0 ? "done" : stopped || !completedAll ? "empty" : "done",
                imageError: errors.length ? errors.slice(0, 3).join("；") : undefined,
                imageProgress: imageProgressState(
                  total,
                  assets.length,
                  stopped ? `已停止，已完成 ${assets.length}/${total} 张` : errors.length ? `部分失败，已完成 ${assets.length}/${total} 张` : `耗时 ${formatDuration(durationSeconds)}`,
                  {
                    failed: failedSlots.size,
                    failedSlots: Array.from(failedSlots).sort((a, b) => a - b),
                    activeIndex: stopped || !completedAll ? assets.length + 1 : undefined,
                    stopped
                  }
                )
              }, parallelImageCollection(id, total, assets, taskSnapshot.prompt, item.imageCollection, Array.from(failedSlots)), item)
            : item
        )
      );
      setServerMessage(stopped ? `节点 ${id} 已停止，保留 ${assets.length} 张。` : errors.length ? `节点 ${id} 部分失败，保留 ${assets.length}/${total} 张。` : `节点 ${id} 并行生成完成，${assets.length}/${total} 张。`);
      settleDeferredImageToolResult(generationRunId, {
        status: stopped || errors.length ? "error" : "done",
        summary: stopped
          ? `已停止，保留 ${assets.length}/${total} 张。`
          : errors.length
            ? `部分失败，已完成 ${assets.length}/${total} 张。`
            : `已完成 ${assets.length}/${total} 张。`,
        detail: `${size} · ${qualityLabel(taskSnapshot.quality)} · ${manualReferences.length} 张参考图`
      });
      await refreshServerState();
    } catch (error) {
      if (!executionScopeIsCurrent(executionScope)) return;
      const message = friendlyImageError(error);
      const durationSeconds = recordImageGenerationDuration(startedAt);
      setNodes((current) =>
        current.map((item) =>
          item.id === id && item.generationRunId === generationRunId
            ? withGeneratedImageContentPresentation({
                ...item,
                status: "review",
                imageState: "error",
                imageError: message,
                imageParams: cloneImageTaskDraft({ ...taskSnapshot, prompt: taskSnapshot.prompt, count: total, size, batchMode: "parallel", referenceImages: taskSnapshot.referenceImages ?? [] }),
                imageProgress: imageProgressState(
                  total,
                  item.assets?.length ?? 0,
                  `生图失败，已停止，已保留 ${item.assets?.length ?? 0} 张。可手动重试。`,
                  { activeIndex: (item.assets?.length ?? 0) + 1, stopped: true }
                ),
                generationRunId,
                prompt: `${nodePrompt}\n\nerror: ${message}\nduration: ${durationSeconds}s`
              }, parallelImageCollection(
                id,
                total,
                item.assets ?? [],
                taskSnapshot.prompt,
                item.imageCollection,
                Array.from({ length: total }, (_slot, slotIndex) => slotIndex + 1).filter((slot) => !(item.assets ?? []).some((asset, compactIndex) => Number(asset.index ?? compactIndex + 1) === slot))
              ), item)
            : item
        )
      );
      setAgentProgress((current) => [
        ...current,
        {
          runId: id,
          projectId: requestProjectId,
          conversationId: requestConversationId,
          phase: "image-error",
          tool: "image_gen",
          summary: message,
          detail: `耗时 ${formatDuration(durationSeconds)}`,
          createdAt: new Date().toISOString()
        }
      ].slice(-48));
      settleDeferredImageToolResult(generationRunId, {
        status: "error",
        summary: message,
        detail: `耗时 ${formatDuration(durationSeconds)}`
      });
      setServerMessage(message);
    } finally {
      markImageRunFinished(id);
      if (Object.keys(imageRunStartsRef.current).length === 0) {
        setAgentStatus("idle");
        setActiveRunStartedAt(null);
      }
      window.setTimeout(() => setActiveNodeId(null), 900);
    }
  }

  function openImageViewer(node: WorkflowNode, index: number) {
    const entries = (node.assets ?? [])
      .map((asset, assetIndex) => ({ asset, assetIndex }))
      .filter((entry) => entry.asset.status !== "pending" && entry.asset.status !== "error" && imageAssetSrc(entry.asset));
    if (entries.length === 0) return;
    const groupedSources = layoutProjection.assetSourcesByHost.get(node.id);
    imageViewerAssetSourcesRef.current = entries.map((entry) => groupedSources?.[entry.assetIndex] ?? { nodeId: node.id, assetIndex: entry.assetIndex });
    const requestedViewerIndex = entries.findIndex((entry) => entry.assetIndex === index);
    setImageViewer({
      nodeId: node.id,
      nodeTitle: node.title,
      assets: entries.map((entry) => entry.asset),
      assetIndices: entries.map((entry) => entry.assetIndex),
      index: requestedViewerIndex >= 0 ? requestedViewerIndex : clamp(index, 0, entries.length - 1)
    });
  }

  function suggestedAssetExportName(node: WorkflowNode, asset: ImageAsset, index: number) {
    const rawExtension = String(asset.path || asset.originalName || "").match(/\.([a-z0-9]{2,5})$/i)?.[1]?.toLowerCase();
    const extension = rawExtension || (node.imageParams?.outputFormat === "jpeg" ? "jpg" : node.imageParams?.outputFormat || "png");
    const title = node.layerGroup
      ? `${String(node.layerGroup.order).padStart(2, "0")}-${node.layerGroup.layerTitle}`
      : (asset.title || node.title || `图片-${index + 1}`);
    return `${title}.${extension}`;
  }

  function openAssetContextMenuAt(event: React.MouseEvent, node: WorkflowNode, assetIndex: number, source: AssetContextMenuState["source"] = "canvas") {
    event.preventDefault();
    event.stopPropagation();
    const asset = node.assets?.[assetIndex];
    if (!asset) return;
    const width = 210;
    const estimatedHeight = node.layerGroup ? 520 : 220;
    setCanvasMenu(null);
    setAssetContextMenu({
      x: Math.round(clamp(event.clientX, 8, Math.max(8, window.innerWidth - width - 8))),
      y: Math.round(clamp(event.clientY, 8, Math.max(8, window.innerHeight - estimatedHeight - 8))),
      nodeId: node.id,
      assetIndex,
      source
    });
  }

  function imageCollectionForNode(node: WorkflowNode): ImageCollection | undefined {
    return node.imageCollection ?? imageContainerSpecForNode(node)?.collection;
  }

  function imageCollectionEntriesForNodeIds(nodeIds: readonly string[]) {
    const entries: Array<{ node: WorkflowNode; collection: ImageCollection }> = [];
    const seen = new Set<string>();
    for (const nodeId of nodeIds) {
      const node = nodesRef.current.find((candidate) => candidate.id === nodeId);
      const collection = node ? imageCollectionForNode(node) : undefined;
      if (!node || !collection || seen.has(collection.id)) continue;
      seen.add(collection.id);
      entries.push({ node, collection });
    }
    return entries;
  }

  function imageCollectionEntriesForCollectionIds(collectionIds: readonly string[]) {
    const byCollectionId = new Map(nodesRef.current.flatMap((node) => {
      const collection = imageCollectionForNode(node);
      return collection ? [[collection.id, { node, collection }] as const] : [];
    }));
    return collectionIds
      .map((id) => byCollectionId.get(String(id || "").trim()))
      .filter((entry): entry is { node: WorkflowNode; collection: ImageCollection } => Boolean(entry));
  }

  function imageCollectionReplacementCandidates(sourceNodeId?: string, sourceAssetIndex?: number) {
    return nodesRef.current
      .filter((candidate) => candidate.type === "image" && candidate.imageState !== "generating")
      .flatMap((candidate) => (candidate.assets ?? []).flatMap((asset, assetIndex) => {
        if (candidate.id === sourceNodeId && assetIndex === sourceAssetIndex) return [];
        if (asset.status === "pending" || asset.status === "error") return [];
        if (!asset.path && !asset.relativePath && !asset.assetUrl && !asset.url) return [];
        return [{ node: candidate, asset, assetIndex }];
      }));
  }

  function openImageCollectionRenameDialog(collectionIds: readonly string[]) {
    const entries = imageCollectionEntriesForNodeIds(collectionIds);
    if (!entries.length) {
      setServerMessage("当前选择没有可重命名的图片组。");
      return;
    }
    setCanvasMenu(null);
    setAssetContextMenu(null);
    setImageCollectionExportDialog(null);
    setImageCollectionDialog({
      mode: "rename",
      collectionIds: entries.map((entry) => entry.collection.id),
      names: Object.fromEntries(entries.map((entry) => [entry.collection.id, entry.collection.name || entry.node.title || "图片组"])),
    });
  }

  function openImageCollectionReplaceDialog(node: WorkflowNode, assetIndex: number) {
    const collection = imageCollectionForNode(node);
    const item = collection ? imageCollectionItemForAsset(node, assetIndex) : undefined;
    if (!collection || !item) {
      setServerMessage("该图片不是可替换的图片组槽位。");
      return;
    }
    const replacement = imageCollectionReplacementCandidates(node.id, assetIndex)[0];
    setCanvasMenu(null);
    setAssetContextMenu(null);
    setImageCollectionExportDialog(null);
    setImageCollectionDialog({
      mode: "replace",
      collectionIds: [collection.id],
      names: {},
      sourceCollectionId: collection.id,
      itemId: item.id,
      requestIndex: item.requestIndex,
      replacementNodeId: replacement?.node.id,
      replacementAssetIndex: replacement?.assetIndex,
      defectReason: "原图存在瑕疵，已替换为新图片。",
    });
  }

  async function submitImageCollectionDialog() {
    const draft = imageCollectionDialog;
    if (!draft || imageCollectionActionBusy) return;
    setImageCollectionActionBusy(true);
    try {
      if (draft.mode === "rename") {
        const requests: RenameImageCollectionRequest[] = draft.collectionIds.map((collectionId) => ({
          collectionId,
          name: draft.names[collectionId] || "图片组",
        }));
        await renameImageCollectionsForAutomation({
          requests,
          expectedProjectId: activeProjectIdRef.current,
          expectedCanvasRevision: canvasRevisionRef.current,
        });
        setServerMessage(`已重命名 ${requests.length} 个图片组。`);
      } else {
        const sourceCollectionId = String(draft.sourceCollectionId || "").trim();
        const replacementNodeId = String(draft.replacementNodeId || "").trim();
        const replacementAssetIndex = Number(draft.replacementAssetIndex);
        const defectReason = String(draft.defectReason || "").trim();
        if (!sourceCollectionId || !replacementNodeId || !Number.isInteger(replacementAssetIndex) || !defectReason) {
          throw automationCommandError("INVALID_ARGUMENT", "请选择替换图片并填写瑕疵原因。");
        }
        await replaceImageCollectionItemsForAutomation({
          requests: [{
            sourceCollectionId,
            ...(draft.itemId ? { itemId: draft.itemId } : {}),
            ...(draft.requestIndex !== undefined ? { requestIndex: draft.requestIndex } : {}),
            replacementNodeId,
            replacementAssetIndex,
            defectReason,
          }],
          expectedProjectId: activeProjectIdRef.current,
          expectedCanvasRevision: canvasRevisionRef.current,
        });
        setServerMessage("图片已替换，原图已保留到独立瑕疵图片组。重复执行相同替换不会生成重复图片。");
      }
      setImageCollectionDialog(null);
    } catch (error) {
      const payload = automationErrorPayload(error);
      setImageCollectionDialog((current) => current ? { ...current, error: payload.error } : current);
      setServerMessage(payload.error);
    } finally {
      setImageCollectionActionBusy(false);
    }
  }

  async function exportImageCollectionsFromUi(collectionIds: readonly string[]) {
    const ids = [...new Set(collectionIds.map((id) => String(id || "").trim()).filter(Boolean))];
    if (!ids.length || imageCollectionActionBusy) return;
    if (!activeProjectIdRef.current) {
      setServerMessage("请先创建或打开项目，再导出图片组。");
      return;
    }
    setCanvasMenu(null);
    setAssetContextMenu(null);
    setImageCollectionDialog(null);
    setImageCollectionActionBusy(true);
    try {
      const format: ImageExportFormat = "png";
      const preview = await previewImageCollectionsForExport({
        collectionIds: ids,
        expectedProjectId: activeProjectIdRef.current,
        format,
      });
      setImageCollectionExportDialog({ collectionIds: ids, format, preview });
    } catch (error) {
      const payload = automationErrorPayload(error);
      setServerMessage(payload.error);
    } finally {
      setImageCollectionActionBusy(false);
    }
  }

  async function refreshImageCollectionExportPreview(format: ImageExportFormat) {
    const draft = imageCollectionExportDialog;
    if (!draft || imageCollectionActionBusy) return;
    setImageCollectionActionBusy(true);
    setImageCollectionExportDialog((current) => current ? { ...current, format, error: undefined } : current);
    try {
      const preview = await previewImageCollectionsForExport({
        collectionIds: draft.collectionIds,
        expectedProjectId: activeProjectIdRef.current,
        format,
      });
      setImageCollectionExportDialog((current) => current && current.collectionIds.join("\0") === draft.collectionIds.join("\0")
        ? { ...current, format, preview, error: undefined }
        : current);
    } catch (error) {
      const payload = automationErrorPayload(error);
      setImageCollectionExportDialog((current) => current ? { ...current, format, error: payload.error } : current);
      setServerMessage(payload.error);
    } finally {
      setImageCollectionActionBusy(false);
    }
  }

  async function confirmImageCollectionExport() {
    const draft = imageCollectionExportDialog;
    if (!draft || imageCollectionActionBusy || !draft.preview.previewToken) return;
    setImageCollectionActionBusy(true);
    try {
      const result = await performImageCollectionExport({
        collectionIds: draft.collectionIds,
        expectedProjectId: activeProjectIdRef.current,
        format: draft.format,
        previewToken: draft.preview.previewToken,
        confirmed: true,
      });
      setImageCollectionExportDialog(null);
      setServerMessage(
        `已导出 ${result.exported?.length ?? draft.collectionIds.length} 个图片组、${result.imageCount ?? 0} 张 ${IMAGE_EXPORT_FORMAT_LABELS[draft.format]} 图片，共 ${formatProjectMigrationBytes(result.totalBytes || 0)}。`,
      );
    } catch (error) {
      const payload = automationErrorPayload(error);
      if (payload.code === "IMAGE_COLLECTION_EXPORT_PREVIEW_STALE") {
        try {
          const preview = await previewImageCollectionsForExport({
            collectionIds: draft.collectionIds,
            expectedProjectId: activeProjectIdRef.current,
            format: draft.format,
          });
          setImageCollectionExportDialog({
            ...draft,
            preview,
            error: "图片组内容或目录已变化，预检数据已刷新，请再次确认。",
          });
          return;
        } catch (refreshError) {
          const refreshedPayload = automationErrorPayload(refreshError);
          setImageCollectionExportDialog((current) => current ? { ...current, error: refreshedPayload.error } : current);
          setServerMessage(refreshedPayload.error);
          return;
        }
      }
      setImageCollectionExportDialog((current) => current ? { ...current, error: payload.error } : current);
      setServerMessage(payload.error);
    } finally {
      setImageCollectionActionBusy(false);
    }
  }

  async function openImageCollectionFolderFromUi(collectionId: string) {
    const id = String(collectionId || "").trim();
    if (!id || imageCollectionActionBusy) return;
    setCanvasMenu(null);
    setAssetContextMenu(null);
    setImageCollectionActionBusy(true);
    try {
      const saved = await flushActiveProjectSession({ live: true, projectId: activeProjectIdRef.current });
      if (!saved?.ok) throw new Error(saved?.error || "打开图片组文件夹前项目尚未可靠保存。");
      const result = await window.naimageConfig?.openImageCollectionFolder?.({
        expectedProjectId: activeProjectIdRef.current,
        collectionId: id,
      });
      if (!result?.ok) {
        if (result?.errorCode === "IMAGE_COLLECTION_NOT_EXPORTED") {
          throw new Error("该图片组尚未导出，请先执行“导出图片组”。");
        }
        throw new Error(result?.error || "打开图片组文件夹失败。");
      }
      addEvent(`打开图片组文件夹 ${result.directoryName || id}`);
    } catch (error) {
      setServerMessage(error instanceof Error ? error.message : String(error));
    } finally {
      setImageCollectionActionBusy(false);
    }
  }

  async function saveAssetAs(node: WorkflowNode, assetIndex: number, format?: ImageExportFormat) {
    const asset = node.assets?.[assetIndex];
    if (!asset) return { ok: false, error: "图片资产不存在。" };
    if (!activeProjectIdRef.current) {
      setServerMessage("请先创建或打开项目，再导出图片。");
      return { ok: false, error: "当前没有打开的项目。" };
    }
    const bridge = window.naimageConfig as typeof window.naimageConfig & {
      saveAssetAs?: (payload: { asset: ImageAsset; projectId?: string; suggestedName?: string; format?: ImageExportFormat }) => Promise<{ ok: boolean; canceled?: boolean; path?: string; format?: ImageExportFormat; cleanupWarning?: string; error?: string }>;
    };
    if (!bridge?.saveAssetAs) {
      setServerMessage("当前版本尚未连接图片另存为服务。");
      return { ok: false, error: "图片另存为服务不可用。" };
    }
    setFileActionBusy(true);
    try {
      const result = await bridge.saveAssetAs({
        asset,
        projectId: activeProjectIdRef.current,
        suggestedName: suggestedAssetExportName(node, asset, assetIndex),
        format
      });
      if (!result.ok && !result.canceled) setServerMessage(result.error || "图片另存为失败。");
      if (result.ok && !result.canceled && result.path) {
        setServerMessage(`已另存图片：${result.path}${imageExportCleanupSuffix(result)}`);
        addEvent(`另存图片 ${node.id}/${assetIndex + 1}`);
      }
      return result;
    } catch (error) {
      const message = friendlyImageError(error);
      setServerMessage(message);
      return { ok: false, error: message };
    } finally {
      setFileActionBusy(false);
      setAssetContextMenu(null);
    }
  }

